import { React, ControlType } from "../core/deps.tsx"
import { HDRI_PRESETS } from "../core/constants.tsx"

function _withRuntimeRoleHidden(
    controls: any,
    hiddenByRole: (props: any) => boolean
) {
    const mapped: any = {}
    Object.entries(controls || {}).forEach(([key, control]: any) => {
        const originalHidden = control?.hidden
        mapped[key] = {
            ...control,
            hidden: (props: any) => {
                if (hiddenByRole(props)) return true
                if (typeof originalHidden === "function")
                    return originalHidden(props)
                return !!originalHidden
            },
        }
    })
    return mapped
}

